for aid,title in titles.items():
 if aid.strip() in meta:meta[aid.strip()]['title']=title
for a in meta.values():
 p=D/(a['id']+'.md');s=p.read_text();s=re.sub(r'\n\nRead more:.*?(?=\n|$)','',s);p.write_text(s)
# Move each original building-role row to the building it describes, not a catch-all article.
name_to_id={a['title'].lower():a['id'] for a in meta.values() if any(e['kind']=='building' for e in a.get('entities',[]))};name_to_id.update({'wall':'walls','temple':'temple','granary':'granary','stone quarry':'stone-quarry'})
for r in migration['records']:
 if r['old_article']!='buildings' or r['section']!='opening' or not r['text'].startswith('| Building |'):continue
 m=re.search(r'^\| \*\*([^*]+)\*\* \|',r['text'],re.M)
 if not m:continue
 target=name_to_id.get(m.group(1).lower());
 if not target:continue
 src=D/(r['home']+'.md');s=src.read_text().replace(r['text'],'').strip();src.write_text(s+'\n')
 dst=D/(target+'.md');dst.write_text(dst.read_text().strip()+'\n\n'+r['text']+'\n');r['home']=target
# Empty former row containers are removed; the parent already links every building.
removed={aid for aid in list(meta) if not (D/(aid+'.md')).read_text().strip()}
for aid in removed:del meta[aid];(D/(aid+'.md')).unlink()
for a in meta.values():
 a['related']=[r for r in a.get('related',[]) if r not in removed]
 p=D/(a['id']+'.md');s=p.read_text()
 for dead in removed:s=re.sub(r'\[\['+re.escape(dead)+r'(?:\|[^]]*)?\]\]','[[buildings]]',s)
 p.write_text(s)
idx['articles']=list(meta.values());(D/'index.json').write_text(json.dumps(idx,ensure_ascii=False,indent=2)+'\n');(R/'fact-migration.json').write_text(json.dumps(migration,ensure_ascii=False,indent=2)+'\n')
print('Curated titles and building rows;',len(meta),'articles')
